/**
 * API types + fetch client.
 *
 * Every type here was generated by hand from the ACTUAL payloads of the FinOps
 * API running with DATA_SOURCE=demo (see services/api/app/main.py). Where the
 * BigQuery path returns a narrower shape than demo, the extra fields are marked
 * optional so both conform. The client renders these; it never recomputes them.
 */

import type { Scope } from "./scope";

const BASE = (import.meta.env.VITE_API_BASE ?? "").replace(/\/$/, "");

// --------------------------------------------------------------------------
// Meta
// --------------------------------------------------------------------------

export interface SourceDescription {
  source: string;
  live: boolean;
  rows?: number;
  focus_version: string;
  conformant?: boolean;
  period_start?: string;
  period_end?: string;
  note?: string;
  // BigQuery path
  table?: string;
  max_bytes_billed?: number;
}

export interface Meta {
  organisation: string;
  environment: string;
  source: SourceDescription;
  ai_enabled: boolean;
  models: { reasoning: string; routing: string };
  focus_version: string;
  personas: string[];
  domains: string[];
  groupable: string[];
}

export interface Dimensions {
  clouds: string[];
  applications: string[];
  business_units: string[];
  environments: string[];
}

// --------------------------------------------------------------------------
// Executive KPIs -- mirrors finops_core.kpi.ExecutiveKPIs (demo path).
// The BigQuery path omits several fields, hence the optionals.
// --------------------------------------------------------------------------

export interface Kpis {
  total_spend: number;
  mom_pct: number | null;
  yoy_pct?: number | null;
  run_rate?: number | null;
  esr_pct: number | null;
  coverage_pct?: number | null;
  utilization_pct: number | null;
  commitment_waste: number;
  cost_of_waste?: number;
  waste_pct?: number | null;
  allocation_coverage_pct: number | null;
  chargeback_readiness: string;
  baseline_drift_pct?: number | null;
  // BigQuery path only
  period_start?: string;
  period_end?: string;
}

