// --------------------------------------------------------------------------
// Fetch plumbing
// --------------------------------------------------------------------------

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
    this.name = "ApiError";
  }
}

/** Append the shared scope to a URLSearchParams. Arrays repeat the key, which
 *  is exactly what FastAPI's `List[str] = Query(None)` expects. */
export function scopeToParams(scope: Scope, extra?: Record<string, string>): URLSearchParams {
  const p = new URLSearchParams();
  if (scope.start) p.set("start", scope.start);
  if (scope.end) p.set("end", scope.end);
  for (const c of scope.clouds) p.append("clouds", c);
  for (const a of scope.applications) p.append("applications", a);
  for (const b of scope.business_units) p.append("business_units", b);
  for (const e of scope.environments) p.append("environments", e);
  if (extra) for (const [k, v] of Object.entries(extra)) p.set(k, v);
  return p;
}

async function getJson<T>(path: string, params?: URLSearchParams, signal?: AbortSignal): Promise<T> {
  const qs = params && [...params].length ? `?${params.toString()}` : "";
  const res = await fetch(`${BASE}${path}${qs}`, { signal });
  if (!res.ok) {
    let detail = res.statusText;
    try {
      const body = await res.json();
      detail = body?.detail ?? detail;
    } catch {
      /* keep statusText */
    }
    throw new ApiError(res.status, detail);
  }
  return (await res.json()) as T;
}

// --------------------------------------------------------------------------
// Endpoints
// --------------------------------------------------------------------------

export const api = {
  meta: (signal?: AbortSignal) => getJson<Meta>("/api/meta", undefined, signal),
  dimensions: (signal?: AbortSignal) => getJson<Dimensions>("/api/dimensions", undefined, signal),

  kpis: (scope: Scope, signal?: AbortSignal) =>
    getJson<Kpis>("/api/kpis", scopeToParams(scope), signal),

  spendMonthly: (scope: Scope, signal?: AbortSignal) =>
    getJson<MonthlyResponse>("/api/spend/monthly", scopeToParams(scope), signal),

  spendBy: (scope: Scope, dimension: string, signal?: AbortSignal) =>
    getJson<SpendByResponse>("/api/spend/by", scopeToParams(scope, { dimension }), signal),

  forecast: (scope: Scope, horizon: number, signal?: AbortSignal) =>
    getJson<ForecastResponse>(
      "/api/forecast",
      scopeToParams(scope, { horizon: String(horizon), include_cliffs: "true" }),
      signal,
    ),

  opportunities: (
    scope: Scope,
    opts: { min_annual_savings?: number; category?: string },
    signal?: AbortSignal,
  ) => {
    const extra: Record<string, string> = {};
    if (opts.min_annual_savings) extra.min_annual_savings = String(opts.min_annual_savings);
    if (opts.category) extra.category = opts.category;
    return getJson<OpportunitiesResponse>(
      "/api/optimize/opportunities",
      scopeToParams(scope, extra),
      signal,
    );
  },

  levers: (signal?: AbortSignal) => getJson<LeversResponse>("/api/optimize/levers", undefined, signal),

  anomalies: (scope: Scope, dimension: string, signal?: AbortSignal) =>
    getJson<AnomaliesResponse>("/api/anomalies", scopeToParams(scope, { dimension }), signal),

  allocation: (scope: Scope, dimension: string, method: string, signal?: AbortSignal) =>
    getJson<AllocationResponse>(
      "/api/allocation",
      scopeToParams(scope, { dimension, method }),
      signal,
    ),

  coverage: (scope: Scope, signal?: AbortSignal) =>
    getJson<CoverageResponse>("/api/governance/coverage", scopeToParams(scope), signal),

  agentTeam: (signal?: AbortSignal) =>
    getJson<AgentTeamResponse>("/api/agent/team", undefined, signal),
};

export const API_BASE = BASE;
